if alpha < 2:
    # Enforce hardness beyond seed
    return (False, None)
# Core logic:
# For the generalized family with weights w_k = k^alpha, a necessary (and in this family, also sufficient) condition
# for the inequality to hold for all nondecreasing sequences satisfying sum equality is:
#   sum_{k=1}^{n-1} k^alpha <= n^alpha.
# This arises from testing the extremal configuration a_1=...=a_{n-1}=x and a_n solving the constraint,
# giving product asymptotics proportional to x^{E(n)} with E(n) = sum_{k=1}^{n-1} k^alpha - n^alpha.
# If E(n) > 0, the product can be made arbitrarily small, violating the inequality.
# Conversely, when E(n) <= 0, the extremal obstruction vanishes; see notes for proof sketch.

# We thus enumerate n >= 1 for which sum_{k=1}^{n-1} k^alpha <= n^alpha.
# The inequality eventually fails for large n because sum_{k=1}^{n-1} k^alpha ~ n^{alpha+1}/(alpha+1) >> n^alpha.

valid_ns = []
